function invitationItems(){return [...mealInvitations.map(i=>({...i,type:'meal'})),...studyInvitations.map(i=>({...i,type:'study'}))];}
function updateInvitationBadge(){if(!window.hfAuth)return;let b=document.querySelector('#invitation-notifications');if(!b){b=document.createElement('button');b.id='invitation-notifications';b.type='button';b.className='notification-button';b.onclick=openInvitationNotifications;document.querySelector('.auth-tools')?.prepend(b);}const n=invitationItems().length;b.innerHTML=`<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg><span>알림</span>${n?`<small>${n}</small>`:''}`;b.setAttribute('aria-label',`알림 · 응답할 초대 ${n}개`);}
async function openInvitationNotifications(){let d=document.querySelector('#invitation-notification-dialog');if(!d){d=document.createElement('dialog');d.id='invitation-notification-dialog';document.body.append(d);}d.innerHTML='<div class="progress-dialog-head"><h2>알림</h2><button type="button" data-notification-close class="dialog-close-icon" aria-label="닫기">×</button></div><p role="status">초대를 확인하고 있습니다…</p>';d.querySelector('[data-notification-close]').onclick=()=>d.close();if(!d.open)d.showModal();try{const result=await Promise.all([mealRequest('/invitations'),studyRequest('/invitations')]);mealInvitations=result[0].invitations;studyInvitations=result[1].invitations;updateInvitationBadge();paintInvitationNotifications(d);}catch(e){d.querySelector('[role=status]').textContent='초대를 불러오지 못했습니다. 닫고 다시 열어 주세요.';}}
function paintInvitationNotifications(d){const items=invitationItems();d.innerHTML=`<div class="progress-dialog-head"><h2>알림 <small>${items.length}</small></h2><button type="button" data-notification-close class="dialog-close-icon" aria-label="닫기">×</button></div><p class="muted">받은 식사·공부 초대 · 응답 전 초대를 모아서 보여드립니다.</p><div class="notification-tabs" role="group" aria-label="초대 종류"><button type="button" data-notification-filter="all" aria-pressed="true">전체 ${items.length}</button><button type="button" data-notification-filter="meal" aria-pressed="false">식사 ${mealInvitations.length}</button><button type="button" data-notification-filter="study" aria-pressed="false">공부 ${studyInvitations.length}</button></div><div class="notification-items">${items.map(i=>`<article class="notification-invite" data-notification-type="${i.type}"><small>${i.type==='meal'?'식사':'공부'} 초대</small><h3>${esc(i.author)}님의 초대</h3><p>${esc(i.restaurant)}</p><p class="muted">${i.kind==='weekly'?esc(i.week)+' 시작 주 · 요일 선택':esc(i.event_time.replace('T',' · '))} · ${i.members.length}/${i.capacity}명 참여</p><div><button type="button" class="primary" data-notification-response="accept" data-type="${i.type}" data-id="${i.id}">${i.kind==='weekly'?'요일 선택하고 수락':'수락하고 참여'}</button><button type="button" class="notification-decline" data-notification-response="decline" data-type="${i.type}" data-id="${i.id}">거절</button></div><p role="status" class="board-status"></p></article>`).join('')}<p class="notification-empty" ${items.length?'hidden':''}>응답할 초대가 없습니다.</p></div>`;d.querySelector('[data-notification-close]').onclick=()=>d.close();}
document.addEventListener('click',async e=>{const filter=e.target.closest('[data-notification-filter]');if(filter){const d=filter.closest('dialog'),type=filter.dataset.notificationFilter;d.querySelectorAll('[data-notification-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===filter)));let count=0;d.querySelectorAll('[data-notification-type]').forEach(a=>{a.hidden=type!=='all'&&a.dataset.notificationType!==type;if(!a.hidden)count++;});d.querySelector('.notification-empty').hidden=!!count;return;}const b=e.target.closest('[data-notification-response]');if(!b)return;const d=b.closest('dialog'),id=Number(b.dataset.id),meal=b.dataset.type==='meal';if(b.dataset.notificationResponse==='accept'){d.close();await(meal?showMealDays:showStudyDays)(id,'respond');return;}const card=b.closest('article');card.querySelectorAll('button').forEach(x=>x.disabled=true);try{await(meal?mealRequest:studyRequest)('/respond',{id,action:'decline'});await openInvitationNotifications();}catch(error){card.querySelector('[role=status]').textContent=error.message;card.querySelectorAll('button').forEach(x=>x.disabled=false);}});
setInterval(()=>{if(window.hfAuth&&typeof mealInvitations!=='undefined'&&typeof studyInvitations!=='undefined')updateInvitationBadge();},1500);

